(()=>{
// A voltage-clamped, single-ion Ohm-law teaching calculation, independent of HH.
const ION_PARAMETERS=Object.freeze({gCl:0.1,gK:0.05,eK:-90});
function ionCurrents({vm=-65,eCl=-75,openA=false,girk=false}={}){
 if(!Number.isFinite(vm)||vm< -100||vm>20||!Number.isFinite(eCl)||eCl< -90||eCl> -40)throw Error('Gradiente fuera del alcance');
 const cl=(openA?ION_PARAMETERS.gCl:0)*(vm-eCl),k=(girk?ION_PARAMETERS.gK:0)*(vm-ION_PARAMETERS.eK);
 const direction=(i,z)=>Math.abs(i)<1e-10?'none':i*z>0?'out':'in';
 return {cl,k,clDirection:direction(cl,-1),kDirection:direction(k,1),vm,eCl,eK:ION_PARAMETERS.eK};
}
function ionReading(s,e){const c=ionCurrents({...s,...e}),signed=x=>(x>0?'+':'')+x.toFixed(2);
 const phrase=(symbol,d,open)=>!open?`${symbol}: canal cerrado, sin flujo por esta vía`:d==='none'?`${symbol}: sin flujo neto, voltaje igual al equilibrio`:`${symbol} ${d==='in'?'entra':'sale'} de la célula`;
 return `${phrase('Cl⁻',c.clDirection,e.openA)}. ICl = ${signed(c.cl)} µA/cm². ${phrase('K⁺',c.kDirection,e.girk)}. IK idealizada = ${signed(c.k)} µA/cm². Signo positivo: corriente convencional saliente. En Cl⁻, cargas negativas que entran producen corriente positiva. El voltaje se mantiene fijo para comparar.`;
}
function renderIonFlow(s,e){const c=ionCurrents({...s,...e});
 const flow=(x,y,ion,d,color)=>{if(d==='none')return `<text x="${x+30}" y="${y-45}" font-size="16" font-family="Arial" fill="${color}">${ion}: sin flujo neto</text>`;
 const a=d==='in'?y-63:y+56,b=d==='in'?y+56:y-63,mid=d==='in'?y+35:y-40;
 return `<g data-ion="${ion}" data-direction="${d}"><path d="M${x},${a}V${b}" stroke="${color}" stroke-width="3"/><path d="M${x-5},${b+(d==='in'?-9:9)}L${x},${b}L${x+5},${b+(d==='in'?-9:9)}" fill="none" stroke="${color}" stroke-width="3"/><circle cx="${x}" cy="${mid}" r="7" fill="${color}" stroke="#fff"/><text x="${x+31}" y="${y-49}" font-size="17" font-family="Arial" fill="${color}">${ion} ${d==='in'?'entra':'sale'}</text></g>`;};
 return `<g data-layer="ionic-flow">${e.openA?flow(350,425+7*Math.sin(350/180),'Cl⁻',c.clDirection,'#245e98'):''}${e.girk?flow(795,425+7*Math.sin(795/180),'K⁺',c.kDirection,'#8a466f'):''}</g>`;
}

const MODES=Object.freeze(['a','b','both']);
const SPEEDS=Object.freeze([0.5,1,2]);
const LAST=12;
function initialScene(mode='both'){if(!MODES.includes(mode))throw Error('Modo inválido');return {mode,step:0,playing:false,speed:1,vm:-65,eCl:-75};}
function sceneTransition(s,action,value){
 if(!MODES.includes(s.mode)||!SPEEDS.includes(s.speed)||!Number.isInteger(s.step)||s.step<0||s.step>LAST||typeof s.playing!=='boolean')throw Error('Estado inválido');
 switch(action){
 case 'mode':if(!MODES.includes(value))throw Error('Modo inválido');return {...s,mode:value,playing:false};
 case 'voltage':if(![-100,-90,-75,-65,-40].includes(value))throw Error('Voltaje inválido');return {...s,vm:value,playing:false};
 case 'chloride':if(![-75,-45].includes(value))throw Error('Equilibrio inválido');return {...s,eCl:value,playing:false};
 case 'speed':if(!SPEEDS.includes(value))throw Error('Velocidad inválida');return {...s,speed:value};
 case 'play':return {...s,step:s.step===LAST?0:s.step,playing:true};
 case 'pause':return {...s,playing:false};
 case 'next':return {...s,step:Math.min(LAST,s.step+1),playing:false};
 case 'back':return {...s,step:Math.max(0,s.step-1),playing:false};
 case 'reset':return {...initialScene(s.mode),speed:s.speed};
 case 'tick':return s.playing?{...s,step:Math.min(LAST,s.step+1),playing:s.step+1<LAST}:{...s};
 default:throw Error('Acción inválida');
 }
}
function sceneEvents(s){const t=s.step;return {a:s.mode!=='b',b:s.mode!=='a',ap:t===1,calcium:t===2,fusion:t===3,released:t>=3&&t<12,boundA:s.mode!=='b'&&t>=5&&t<=7,boundB:s.mode!=='a'&&t>=5&&t<=7,openA:s.mode!=='b'&&t>=5&&t<=7,gi:s.mode!=='a'&&t>=6&&t<=9,girk:s.mode!=='a'&&t>=7&&t<=9,dissociation:t===8,diffusionOut:t===9,uptake:t===10,intracellular:t===11,rest:t===12};}
// Same schematic release for every display mode: no receptor-selection input.
function sceneLigands(step){
 if(step<3||step>=12)return [];
 if(step===3)return [[433,242],[452,251],[429,266]];
 if(step<=8)return [[384,276],[478,296],[535,252],[275,332],[455,330],[695,304],[850,290]];
 if(step===9)return [[65,260],[18,320],[155,355],[855,281],[889,325]];
 if(step===10)return [[160,188],[942,352]];
 return [[160,137],[985,405]];
}
const STAGES=Object.freeze([
 ['Una liberación, dos vías','Objetivo: explicar cómo la misma liberación de GABA activa un canal o una vía que regula otro canal. Elige qué receptores mostrar, haz tu predicción y avanza.'],
 ['Llega la señal presináptica','Comenzamos con una señal que ya alcanzó el terminal. Su generación se estudia en el módulo separado «Potencial de acción». Aquí seguimos la comunicación química.'],
 ['Entra calcio','La despolarización abre canales de Ca²⁺; su entrada local ayuda a activar la maquinaria que fusiona las vesículas con la membrana.'],
 ['La vesícula libera GABA','La vesícula se fusiona con la membrana y abre su contenido al exterior: exocitosis. Los símbolos dorados representan GABA, sin contar moléculas reales.'],
 ['GABA se dispersa por difusión','El movimiento molecular al azar dispersa GABA por el espacio entre membranas. No hay una ruta dirigida hacia los receptores.'],
 ['GABA se une por fuera','La unión es reversible. En GABA-A, el propio receptor permite conducir iones; GABA-B es una proteína receptora distinta del canal que regulará.'],
 ['GABA-B comunica con Gi/o','Gi/o es una familia de proteínas G: interruptores moleculares dentro de la célula. La activación de GABA-B permite que sus componentes transmitan la señal.'],
 ['Dos maneras de cambiar la conductancia','GABA-A es un canal de aniones. En la rama elegida de GABA-B, Gβγ regula el canal de potasio GIRK. Esa vía indirecta suele dar una respuesta más lenta y prolongada; aquí no se calculan sus tiempos.'],
 ['GABA puede separarse','El GABA unido puede disociarse. Se muestra el cierre de GABA-A y una señal G todavía activa para explicar que separarse no apaga instantáneamente toda la vía indirecta.'],
 ['La difusión también lo aleja','Parte del GABA se dispersa fuera de la zona cercana a los receptores. Alejarse reduce su disponibilidad local: la molécula no se destruye en la hendidura.'],
 ['Los transportadores captan GABA','Proteínas de la membrana pueden llevar GABA al interior de neuronas o astrocitos, células gliales cercanas. Captación y difusión pueden ocurrir al mismo tiempo; aquí las separamos para aprender.'],
 ['Después se reutiliza o metaboliza dentro','En la neurona, parte del GABA captado puede volver a almacenarse en vesículas. Dentro de las células, GABA-T participa en su metabolismo, asociado a mitocondrias. No se dibuja degradación enzimática extracelular.'],
 ['La escena vuelve a reposo','La comunicación termina al disminuir GABA disponible y desactivarse los receptores y sus vías. Volver al inicio permite comparar ambas familias con la misma secuencia de liberación.']
]);
function sceneText(s){
 if(s.mode==='a'&&s.step===6)return ['GABA-A ya conduce iones','El propio receptor forma el canal: su apertura cambia la facilidad con que pasa corriente. No necesita la cadena de proteína G que hemos ocultado en esta vista.'];
 if(s.mode==='a'&&s.step===7)return ['El gradiente determina la corriente','Abrir GABA-A no impone una dirección universal al voltaje. El efecto depende del potencial de reversión y de los gradientes de los iones; despolarizar no significa siempre excitar.'];
 if(s.mode==='b'&&s.step===5)return ['GABA se une a GABA-B','La unión ocurre por fuera. GABA-B no es un poro: comunicará con una proteína G situada dentro de la célula.'];
 if(s.mode==='b'&&s.step===7)return ['La proteína G regula GIRK','Gβγ, componentes de la proteína G, regula GIRK: un canal de potasio separado. Esta vía indirecta suele responder de forma más lenta y prolongada. La escena no calcula su duración ni la dirección de la corriente.'];
 if(s.mode==='a'&&s.step===8)return ['GABA se separa y el canal se cierra','La unión de GABA al receptor es reversible. Al separarse disminuye la activación del canal; esta escena divide esos procesos en etapas de lectura.'];
 return STAGES[s.step];
}
function sceneFeedback(answer){if(!answer)return 'Elige una predicción y compruébala en las etapas de receptores.';if(answer==='inside')return 'GABA se une por fuera a GABA-B; no necesita entrar para activarlo. La señal se comunica hacia dentro mediante Gi/o y Gβγ, que regulan el canal GIRK.';return answer==='separate'?'Coincide: GABA-A contiene el canal; GABA-B activa una vía de proteína G que regula GIRK, un canal separado.':'Revisa la escena: GABA-B no deja pasar iones a través de un poro propio. Gi/o y Gβγ comunican con el canal GIRK.';}

function renderScene(s){
 const e=sceneEvents(s),pre=x=>207+12*Math.cos((x-480)/245),post=x=>425+7*Math.sin(x/180);
 const pts=Array.from({length:51},(_,i)=>i*18);
 const lipid=(x,y,flip=1)=>`<g transform="translate(${x} ${y}) scale(1 ${flip})"><path d="M-3,3l-2,8m8,-8l2,8" stroke="#597f7d" stroke-width="1.2"/><ellipse rx="4.6" ry="3.6" fill="url(#v4-lipid)" stroke="#597f7d" stroke-width=".7"/></g>`;
 const ribbon=(fn,isPre=false)=>{const groups=e.fusion&&isPre?[pts.filter(x=>x<403),pts.filter(x=>x>477)]:[pts];return groups.map(g=>`<path d="M${g[0]},${fn(g[0])-10}${g.map(x=>`L${x},${fn(x)-10}`).join('')}${[...g].reverse().map(x=>`L${x},${fn(x)+10}`).join('')}Z" fill="url(#v4-membrane)" stroke="#789c8b" stroke-width=".8"/>`).join('');};
 const bilayer=pts.map(x=>(e.fusion&&Math.abs(x-440)<37?'':lipid(x,pre(x)-8)+lipid(x,pre(x)+8,-1))+lipid(x,post(x)-8)+lipid(x,post(x)+8,-1)).join('');
 const vesicle=(x,y,r,dim=false)=>`<g opacity="${dim?.5:1}"><circle cx="${x+2}" cy="${y+5}" r="${r}" fill="#507d7018"/><circle cx="${x}" cy="${y}" r="${r}" fill="url(#v4-vesicle)" stroke="#749777" stroke-width="3"/><circle cx="${x}" cy="${y}" r="${r-6}" fill="none" stroke="#c1d0a9" stroke-width="2"/>${[[-9,-7],[8,-9],[0,3],[-8,10],[10,9]].map(([a,b])=>`<circle cx="${x+a}" cy="${y+b}" r="4.5" fill="url(#v4-gaba)"/>`).join('')}</g>`;
 const channel=(x,y,open,kind='a')=>`<g data-channel="${kind}" transform="translate(${x} ${y})"><ellipse cy="18" rx="30" ry="9" fill="#294b4e20"/><rect x="-7" y="-12" width="14" height="37" rx="3" fill="${open?'#f9fff6':'#8dafa3'}"/><path d="M-20,-32C-36,-20 -27,-3 -27,14Q-25,36 -7,26L-6,-10Q-6,-30 -20,-32Z M20,-32C36,-20 27,-3 27,14Q25,36 7,26L6,-10Q6,-30 20,-32Z" fill="url(#v4-${kind==='a'?'receptor':'blue'})" stroke="#567b78" stroke-width="2"/>${open?'<path d="M0,-17V22" stroke="#f9fff6" stroke-width="7" stroke-linecap="round"/>':'<path d="M-7,2H7" stroke="#567b78" stroke-width="8" stroke-linecap="round"/>'}</g>`;
 const gold=(x,y,bound=false)=>`<circle data-gaba="${bound?'bound':'free'}" cx="${x}" cy="${y}" r="6.3" fill="url(#v4-gaba)" stroke="#b77c2d" stroke-width=".6" class="${s.step===4&&!bound?'v4-diffuse':''}" style="animation-delay:-${(x+y)%7/2}s;animation-play-state:${s.playing?'running':'paused'}"/>`;
 const transport=(x,y,angle=0)=>`<g transform="translate(${x} ${y}) rotate(${angle})"><path d="M-12,-17Q-22,0 -12,17H-3V-17Z M12,-17Q22,0 12,17H3V-17Z" fill="url(#v4-transporter)" stroke="#7c638c" stroke-width="1.8"/></g>`;
 const clearDots=s.step>=10?'':sceneLigands(s.step).map(([x,y])=>gold(x,y)).join('');
 const chosenA=e.a?`${channel(350,post(350),e.openA)}${e.boundA?gold(329,post(350)-29,true):''}<text x="311" y="518" class="protein" font-family="Arial, Helvetica, sans-serif" font-size="20" font-weight="bold" fill="#28483f">GABA-A</text><text x="285" y="544" class="small" font-family="Arial, Helvetica, sans-serif" font-size="16" font-weight="normal" fill="#28483f">Receptor = canal</text>`:'';
 const label=(x,y,text,size=16)=>`<text x="${x}" y="${y}" font-family="Arial, Helvetica, sans-serif" font-size="${size}" fill="#28483f">${text}</text>`;
 // The protein exists before activation. Only its signalling state changes.
 const gProtein=`<g data-protein="Gi/o" data-state="${e.gi?'active':'resting'}" aria-label="Proteína Gi/o intracelular, ${e.gi?'activa':'en reposo'}, componentes alfa, beta y gamma">
 <path d="M591,461Q610,470 621,476" stroke="#668a91" stroke-width="2" fill="none"/>
 <g data-subunit="alpha"><ellipse cx="648" cy="478" rx="27" ry="19" fill="url(#v4-blue)" stroke="#426a7e" stroke-width="1.5"/>${label(642,484,'α',18)}</g>
 <g data-subunit="beta-gamma" transform="translate(${e.gi?32:0} 0)"><ellipse cx="689" cy="477" rx="20" ry="16" fill="#7eaaac" stroke="#426a7e" stroke-width="1.5"/><ellipse cx="711" cy="468" rx="10" ry="11" fill="#b4d0bd" stroke="#426a7e" stroke-width="1.5"/>${label(683,483,'β',17)}${label(707,473,'γ',15)}</g>
 ${e.gi?'<path d="M755,475Q773,464 783,452" stroke="#537b99" stroke-width="2.5" fill="none" marker-end="url(#v4-arrow)"/>':''}
 ${label(622,564,e.gi?'Gi/o activa':'Gi/o · complejo αβγ')}
 ${label(622,586,e.gi?'Gβγ regula GIRK':'Proteína G en reposo')}
 </g>`;
 const chosenB=e.b?`<g data-receptor="GABA-B" transform="translate(575 ${post(575)})"><path d="M-26,-39C-53,-75 -11,-83 -4,-53C9,-85 46,-70 29,-38Q47,-11 24,11L20,31Q8,52 -9,29Q-42,31 -26,-2Z" fill="url(#v4-blue)" stroke="#567b78" stroke-width="2"/><path d="M-16,-21Q18,-37 20,-14" stroke="#c8e1db" stroke-width="4" fill="none"/></g>${e.boundB?gold(575,post(575)-54,true):''}${channel(795,post(795),e.girk,'girk')}<text x="536" y="518" class="protein" font-family="Arial, Helvetica, sans-serif" font-size="20" font-weight="bold" fill="#28483f">GABA-B</text><text x="755" y="518" class="protein" font-family="Arial, Helvetica, sans-serif" font-size="20" font-weight="bold" fill="#28483f">GIRK · K⁺</text><text x="747" y="544" class="small" font-family="Arial, Helvetica, sans-serif" font-size="16" font-weight="normal" fill="#28483f">Canal separado</text>${gProtein}`:'';
 return `<svg font-family="Arial, Helvetica, sans-serif" font-size="18" fill="#28483f" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1100 650" role="img" aria-label="${sceneText(s)[0]}. Un terminal libera GABA sobre membrana postsináptica; astrocito a la derecha. Ilustración sin escala."><style>text{font:18px Arial,Helvetica,sans-serif;fill:#28483f}.region{font-size:17px;letter-spacing:1px;font-weight:bold}.protein{font-size:20px;font-weight:bold}.small{font-size:16px}.tiny{font-size:14px}</style><defs><radialGradient id="v4-lipid" cx=".3" cy=".25"><stop stop-color="#d7e5bd"/><stop offset=".65" stop-color="#96b5a4"/><stop offset="1" stop-color="#638d80"/></radialGradient><linearGradient id="v4-membrane" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#d0dabb"/><stop offset=".5" stop-color="#748e79"/><stop offset="1" stop-color="#c5d3bd"/></linearGradient><linearGradient id="v4-pre" x2=".2" y2="1"><stop stop-color="#bad5c7"/><stop offset="1" stop-color="#e2e8cc"/></linearGradient><linearGradient id="v4-post" x2=".2" y2="1"><stop stop-color="#d1e1dc"/><stop offset="1" stop-color="#adc9c5"/></linearGradient><linearGradient id="v4-astro"><stop stop-color="#dbd5e6"/><stop offset="1" stop-color="#b3c2d4"/></linearGradient><radialGradient id="v4-vesicle" cx=".3" cy=".25"><stop stop-color="#fffce8"/><stop offset=".65" stop-color="#e7e7b8"/><stop offset="1" stop-color="#a6c098"/></radialGradient><radialGradient id="v4-gaba" cx=".3" cy=".25"><stop stop-color="#fff1b9"/><stop offset=".6" stop-color="#e6a746"/><stop offset="1" stop-color="#b9762d"/></radialGradient><linearGradient id="v4-receptor"><stop stop-color="#5b8f7f"/><stop offset=".5" stop-color="#a8c49c"/><stop offset="1" stop-color="#5d9484"/></linearGradient><linearGradient id="v4-blue"><stop stop-color="#567f99"/><stop offset=".5" stop-color="#a4c5cf"/><stop offset="1" stop-color="#557d95"/></linearGradient><linearGradient id="v4-transporter"><stop stop-color="#8e78a4"/><stop offset=".5" stop-color="#d1b8d8"/><stop offset="1" stop-color="#8a73a0"/></linearGradient><radialGradient id="v4-glow"><stop stop-color="#ffe0a0" stop-opacity=".9"/><stop offset="1" stop-color="#ffe0a0" stop-opacity="0"/></radialGradient><marker id="v4-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0,0L6,3L0,6" fill="#537b99"/></marker></defs><rect width="1100" height="650" rx="24" fill="#f8f6ee"/><path d="M0,0H940Q995,120 900,${pre(900)}${[...pts].reverse().map(x=>`L${x},${pre(x)}`).join('')}Z" fill="url(#v4-pre)"/><path d="M0,${post(0)}${pts.map(x=>`L${x},${post(x)}`).join('')}Q965,505 940,650H0Z" fill="url(#v4-post)"/><path d="M1100,195Q1004,211 974,278Q922,337 956,408Q999,465 944,531Q914,599 980,650H1100Z" fill="url(#v4-astro)" stroke="#9ea7be" stroke-width="2"/>${ribbon(pre,true)}${ribbon(post)}${bilayer}<text x="26" y="39" class="region" font-family="Arial, Helvetica, sans-serif" font-size="17" font-weight="bold" fill="#28483f">TERMINAL PRESINÁPTICO</text><text x="26" y="300" class="region" font-family="Arial, Helvetica, sans-serif" font-size="17" font-weight="bold" fill="#28483f">HENDIDURA</text><text x="26" y="489" class="region" font-family="Arial, Helvetica, sans-serif" font-size="17" font-weight="bold" fill="#28483f">MEMBRANA</text><text x="26" y="514" class="region" font-family="Arial, Helvetica, sans-serif" font-size="17" font-weight="bold" fill="#28483f">POSTSINÁPTICA</text><text x="963" y="263" class="region" font-family="Arial, Helvetica, sans-serif" font-size="17" font-weight="bold" fill="#28483f">ASTROCITO</text>${vesicle(220,108,25,true)}${vesicle(675,94,28,true)}${s.step<3?vesicle(440,158,36):''}${e.ap?'<ellipse cx="445" cy="135" rx="220" ry="70" fill="url(#v4-glow)"/><text x="552" y="149">Señal presináptica</text>':''}${e.fusion?`<path d="M403,${pre(440)}C413,198 390,169 403,135C416,97 461,97 475,135C488,169 465,198 477,${pre(440)}" fill="url(#v4-vesicle)" stroke="#749777" stroke-width="3"/><text x="510" y="152">Fusión vesicular</text><path d="M499,157L480,184" stroke="#6c8173"/>`:''}${channel(290,pre(290),e.calcium,'ca')}<text x="249" y="157">Ca²⁺</text>${e.calcium?'<path d="M289,260V173" stroke="#537b99" stroke-width="2.5" marker-end="url(#v4-arrow)"/><circle cx="290" cy="252" r="5" fill="#81abc8"/><circle cx="290" cy="183" r="5" fill="#81abc8"/>':''}${transport(160,pre(160))}${transport(946,354,90)}<text x="37" y="149" class="small" font-family="Arial, Helvetica, sans-serif" font-size="16" font-weight="normal" fill="#28483f">Transportador</text><path d="M143,155L157,179" stroke="#7c638c"/><text x="954" y="321" class="small" font-family="Arial, Helvetica, sans-serif" font-size="16" font-weight="normal" fill="#28483f">Transportador</text>${clearDots}${chosenA}${chosenB}${renderIonFlow(s,e)}${e.uptake?`<path d="M160,251V174 M905,354H982" stroke="#8b6fa0" stroke-width="2.5" fill="none" marker-end="url(#v4-arrow)"/>${gold(160,188)}${gold(942,352)}<text x="28" y="365">Captación hacia el interior</text>`:''}${e.intracellular?`${vesicle(160,135,28)}<text x="56" y="77" class="small" font-family="Arial, Helvetica, sans-serif" font-size="16" font-weight="normal" fill="#28483f">Reutilización en vesículas</text><path d="M970,420C945,403 960,382 989,384C1027,383 1054,414 1031,432C1011,447 988,436 970,420Z" fill="#cbd4b3" stroke="#859879" stroke-width="2"/><path d="M974,397l16,17l6,-19l14,24l15,-12" fill="none" stroke="#859879" stroke-width="2"/>${gold(979,411)}<path d="M991,413H1005" stroke="#537b99" stroke-width="1.8" marker-end="url(#v4-arrow)"/><path d="M1017,405l6,6l-6,6l-6,-6Z" fill="#8d789c"/><text x="956" y="464" class="small" font-family="Arial, Helvetica, sans-serif" font-size="16" font-weight="normal" fill="#28483f">Mitocondria</text><text x="957" y="487" class="small" font-family="Arial, Helvetica, sans-serif" font-size="16" font-weight="normal" fill="#28483f">GABA-T</text><text x="948" y="509" class="tiny" font-family="Arial, Helvetica, sans-serif" font-size="14" font-weight="normal" fill="#28483f">Metabolismo interno</text>`:''}${e.diffusionOut?'<text x="29" y="390" class="small" font-family="Arial, Helvetica, sans-serif" font-size="16" font-weight="normal" fill="#28483f">GABA se dispersa fuera de la zona sináptica</text>':''}<text x="28" y="620" class="small" font-family="Arial, Helvetica, sans-serif" font-size="16" font-weight="normal" fill="#28483f">Corte didáctico · posiciones, tamaños y etapas sin escala física</text></svg>`;
}

const el=id=>document.getElementById(id);let scene=initialScene(),clock=null,zoomed=false;
function clearClock(){if(clock!==null)clearInterval(clock);clock=null;}
function paint(){const [title,why]=sceneText(scene);el('stage-title').textContent=title;el('stage-text').textContent=why;el('progress').textContent=`Etapa ${scene.step+1} de ${LAST+1} · ${scene.playing?'reproduciendo':'pausada'}`;el('scene-picture').innerHTML=renderScene(scene);el('previous').disabled=scene.step===0;el('next').disabled=scene.step===LAST;el('play-pause').textContent=scene.playing?'Pausar':'Reproducir';el('voltage').value=String(scene.vm);el('chloride').value=String(scene.eCl);el('ion-reading').textContent=ionReading(scene,sceneEvents(scene));el('mode').value=scene.mode;el('speed').value=String(scene.speed);el('compare-note').textContent='La misma liberación de GABA se conserva al cambiar la vista. El recorrido se pausa en la misma etapa para comparar.';}
function schedule(){clearClock();if(scene.playing)clock=setInterval(()=>{scene=sceneTransition(scene,'tick');paint();if(!scene.playing)clearClock();},3500/scene.speed);}
function act(action,value){scene=sceneTransition(scene,action,value);paint();schedule();if(action==='reset'){el('prediction').value='';el('feedback').textContent=sceneFeedback('');}}
el('voltage').onchange=()=>act('voltage',+el('voltage').value);el('chloride').onchange=()=>act('chloride',+el('chloride').value);el('mode').onchange=()=>act('mode',el('mode').value);el('speed').onchange=()=>act('speed',+el('speed').value);el('next').onclick=()=>act('next');el('previous').onclick=()=>act('back');el('reset').onclick=()=>act('reset');el('play-pause').onclick=()=>act(scene.playing?'pause':'play');el('check').onclick=()=>{el('feedback').textContent=sceneFeedback(el('prediction').value);};
el('zoom').onclick=()=>{zoomed=!zoomed;el('scene-picture').className=zoomed?'scene-scroll is-zoomed':'scene-scroll';el('zoom').textContent=zoomed?'Ver corte completo':'Ampliar dibujo';el('zoom').setAttribute('aria-pressed',String(zoomed));};
paint();

})();
